        name: "Barbell Bent Over Row",
        category: "Back",
        muscleGroups: [
            "Middle Back",
            "Lats",
            "Rear Delts",
            "Upper Back"
        ],
        equipment: "Barbell",
        instructions: "A thickness-building compound exercise for the Lats, Rear Delts and Upper Back. The barbell allows for maximal loading and overall strength development. Vital for posture and back width. 1. Stand with feet shoulder-width apart, holding the barbell, and hinge forward at your hips. 2. Keep your back flat, chest up, and knees slightly bent, letting the arms hang straight down. 3. Pull the weight toward your torso by driving your elbows back, squeezing your shoulder blades together. 4. Squeeze your lats hard at the peak of the movement. 5. Extend your arms to return the weight to the starting position, feeling a stretch in your back. 6. Maintain constant tension on the muscle and avoid using momentum.",
