        ],
        equipment: "Barbell",
        instructions: "A compound pushing movement that builds mass and strength in the Chest, Front Delts and Triceps. The barbell allows for maximal loading and overall strength development. Key for upper body pushing power. 1. Sit on a bench with your feet planted firmly on the floor, holding barbell. 2. Retract your shoulder blades and hold the weight directly above your chest with arms extended. 3. Lower the weight to your chest with control, keeping elbows at a 45-degree angle. 4. Press the weight back up explosively to the starting position. 5. Repeat for the desired number of repetitions, keeping your feet planted. 6. Keep your wrists straight and strong throughout the lift.",
