        instructions: "The premier lower body builder, targeting the Quads, Glutes, and Hamstrings. The barbell allows for maximal loading and overall strength development. Fundamental for leg size, strength, and athletic power. 1. Stand with feet shoulder-width apart, positioning the barbell appropriately. 2. Brace your core, keep your chest up, and ensure the weight is balanced comfortably. 3. Lower your hips back and down as if sitting in a chair, keeping your knees tracking over your toes. 4. Stand tall at the top, extending your hips fully without overextending your back. 5. Drive back up to the starting position, keeping your chest up. 6. Keep your spine neutral and heels planted throughout the movement.",
