        equipment: "Dumbbells",
        instructions: "A forearm isolation exercise targeting the Biceps and Forearms. Dumbbells allow for a greater range of motion and unilateral development, fixing imbalances. Unilateral training identifies and corrects strength asymmetries. Improves grip strength and wrist stability. 1. Sit on a bench with your feet planted firmly on the floor, holding dumbbells. 2. Keep your elbows pinned to your sides and palms facing forward (underhand grip). 3. Contract your biceps to curl the weight up, keeping your upper arms stationary. (Perform all reps on one side first). 4. Squeeze your biceps hard at the peak of the movement. 5. Lower the weight slowly, resisting gravity until your arms are fully extended. 6. Maintain constant tension on the muscle and avoid using momentum.",
