        instructions: "A powerhouse posterior chain exercise hitting the Glutes, Hamstrings and Lower Back. The barbell allows for maximal loading and overall strength development. Focuses heavily on the hip hinge pattern for hamstring development. Builds total body strength and real-world power. 1. Stand with feet shoulder-width apart, positioning the barbell appropriately. 2. Keep your back flat, chest up, and hips down, with the bar close to your shins. 3. Drive through your heels and extend your hips to lift the weight, keeping the bar close to your body. 4. Stand tall at the top, extending your hips fully without overextending your back. 5. Lower the weight with control by hinging at the hips, reversing the upward movement. 6. Keep your spine neutral and heels planted throughout the movement.",
